    } else if (c == ',') {
      // End of note, add to result and reset
      if (currentNoteIndex != -1) {
        var noteValue = (currentNoteIndex * 2 + (isSharp ? 1 : 0));
        return [noteValue];
      }
    } else if (c == '-') {
      // Rest, represented by '-', which has value 0
      return [0];
    } else {
