    if (noteNames.contains(char)) {
      int index = noteNames.indexOf(char);
      int noteValue = (index + 24) % 12;
      int newOctave = currentNoteIndex / 12;

      if (isSharpOrFlat) {
        if (modifier == '#') {
          noteValue += 1;
        } else if (modifier == '-') {
          noteValue -= 1;
        }

        // Adjust to stay within the same octave range by adding/subtracting octaves as needed
        while (noteValue >= 12 * (newOctave + 1)) {
          noteValue -= 12;
        }
        while (noteValue <= 12 * (newOctave - 1)) {
          noteValue += 12;
        }
      }

      currentNoteIndex = noteValue;
      notes.add(currentNoteIndex);
    } else if ('1' <= char && char <= '8') {
      // If it's an octave number, adjust the current note accordingly
      int octaveNumber = int.parse(char);
      int totalNotesInOctave = 12;
      int baseNoteValue = (currentNoteIndex % totalNotesInOctave) + (octaveNumber - 1) * totalNotesInOctave;
      currentNoteIndex = baseNoteValue;
      notes.add(baseNoteValue);
    }
  }

  return notes;
}

