List<int> parseMusic(String musicString) {
  final List<String> notes = ['C', 'D', 'E', 'F', 'G', 'A', 'B'];
  final int noteLength = notes.length;

  final String pattern = r'([CD][#]?|R)';
  final RegExp regExp = new RegExp(pattern);
  final Iterable<Match> matches = regExp.allMatches(musicString);

  final List<int> result = [];

  for (final Match match in matches) {
    if (match.group(1) == null || match.group(1).isEmpty) continue;

    var symbol = match.group(1)!;

    // Check if it's a rest
    if (symbol == "R") {
      result.add(-1);
      continue;
    }

    // Get the index of this note, or throw an error.
    try {
      var idx = notes.indexOf(symbol);

      // If we have sharp, add 1 to the index. 
      // e.g., C# -> D
      if (symbol.contains('#')) {
        idx += 1;
      }

      // Ensure that the index is within valid range.
      if (idx < 0 || idx >= noteLength) {
        throw Exception("Invalid note");
      }
      result.add(idx);
    } catch (_) {
      throw Exception("Invalid note $symbol");
    }
  }

  return result;
}

