String antiShuffle(String s) {
  if (s.isEmpty || s.length == 1) return s;

  List<String> words = [];
  String currentWord = '';

  for (int i = 0; i < s.length; i++) {
    final char = s[i];

    // Check if the character is a space or punctuation
    if (!char.isLetter && !char.isDigit) {
      // If it's not part of the word, finalize the current word and start new one
      if (currentWord.isNotEmpty) {
        words.add(currentWord);
        currentWord = '';
      }
      words.add(char); // Add the non-letter/digit character as its own token
    } else {
      // Otherwise, add to current word
      currentWord += char;
    }
  }

  // Handle any remaining characters after loop ends
  if (currentWord.isNotEmpty) {
    words.add(currentWord);
  }

  // Shuffle each word but keep their order in the list
  List<String> shuffledWords = [];
  for (var word in words) {
    if (word.trim().isNotEmpty) { // Skip empty strings from possible spaces/punctuation
      final chars = word.split('');
      Random random = Random();
      chars.sort((a, b) => random.nextInt(2) - 1);
      shuffledWords.add(chars.join());
    }
  }

  return shuffledWords.join(' ');
}

