        String c = word[i];
        if (c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U') {
          numVowelsInRest++;
        } else if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
          numVowelsInRest++;
        }
      }

      // If there are at least two vowels, increment count
      if (numVowelsInRest >= 2) {
        count++;
      }
    }
  }

