  if (arr.isEmpty || k <= 0) return 0;

  final n = arr.length;
  for (var i = 0; i < n; i++) {
    var sum = 0;
    var count = 0;

    while (count < k && i + count < n) {
      sum += arr[i + count];
      count++;
    }

    if (sum % 2 == 1) {
      sum -= 1;
    }

    arr[i] = sum;
  }

  return arr.reduce((a, b) => a + b);
}

