          currentMin = min(currentMin, dp[i-1][j]);
        }
      }
      if (j > 0) {
        if (dp[i][j-1] != -inf) {
          currentMin = min(currentMin, dp[i][j-1]);
        }
      }

      // Update the current cell with the minimum value found
      dp[i][j] = currentMin + grid[i][j];
    }
  }

  // Find the smallest value at the last row and select its index
  int resultIndex = 0;
  for (int j = 1; j < cols; ++j) {
    if (dp[rows-1][j] < dp[rows-1][resultIndex]) {
      resultIndex = j;
    }
  }

