  while (!queue.isEmpty) {

    final curr = queue.removeFirst(); 
    final row = curr[0];
    final col = curr[1];
    final cost = curr[2]; 

    // If we have collected all the coins and reached bottom-right corner
    if (row == rows-1 && col == cols-1) {
