      final newCol = col + directions[dir * 2 + 1];

      if (newRow >= 0 && newRow < rows &&
          newCol >= 0 && newCol < cols) {

        final nextCost = cost + grid[newRow][newCol];

        if (nextCost <= k && !visited[newRow].contains(newCol)) {
          visited[newRow].add(newCol);
          queue.add([newRow, newCol, nextCost]);
        } else if (nextCost > k) continue;
      }
    }
