List<int> minPath(List<List<int>> grid, int k) {
  final rows = grid.length;
  if (rows == 0) return [];
  final cols = grid[0].length;

  // Initialize a list of lists to keep track of the minimum path sums
  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));

  // Base case for first row and column
  dp[0][0] = grid[0][0];
  for (int i = 1; i < rows; ++i) {
    dp[i][0] = dp[i - 1][0] + grid[i][0];
  }
  for (int j = 1; j < cols; ++j) {
    dp[0][j] = dp[0][j - 1] + grid[0][j];
  }

  // Fill in the rest of the DP table
  for (int i = 1; i < rows; ++i) {
    for (int j = 1; j < cols; ++j++) {
      dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + grid[i][j];
    }
  }

  // Now reconstruct the path with exactly k elements by backtracking through the DP table
  // We need to find a path from top-left to bottom-right that has exactly k steps,
  // which means it goes through (k-1) cells. So we need to find such a path.

  // The total number of possible paths is not directly relevant here, but we are interested 
  // only in the minimal sum path that uses exactly k moves.

  // Let's backtrack starting from the end to the start, choosing directions based on where the minimal value came from
  var currentRow = rows - 1;
  var currentCol = cols - 1;
  final result = [grid[currentRow][currentCol]];
  int count = 1;

  while (count < k && currentRow > 0 && currentCol > 0) {
    if (dp[currentRow - 1][currentCol] <= dp[currentRow][currentCol - 1]) {
      currentRow--;
    } else {
      currentCol--;
    }
    result.add(grid[currentRow][currentCol]);
    count++;
  }

  // If we reach this point, then either:
  // 1. We have found all k steps and can stop
  // 2. Or, we've reached an edge and must continue along one direction until reaching the other edge

  while (count < k) {
    if (currentRow == 0) {
      currentCol--;
      result.add(grid[currentRow][currentCol]);
      count++;
    } else if (currentCol == 0) {
      currentRow--;
      result.add(grid[currentRow][currentCol]);
      count++;
    } else {
      break; // This should never happen because the original problem states there exists at least one valid path
    }
  }

  return result.reversed.toList(); // Reverse since we built it backwards
}

